<?php $title='Register';include 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($_POST['password']!==$_POST['confirm'])flash('danger','Passwords do not match.');else{try{$st=db()->prepare('INSERT INTO users(full_name,email,phone,password_hash) VALUES(?,?,?,?)');$st->execute([trim($_POST['full_name']),trim($_POST['email']),trim($_POST['phone']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('success','Account created. Please login.');header('Location: login.php');exit;}catch(Exception $e){flash('danger','Email already exists or registration failed.');}}} ?><section class="section"><div class="container" style="max-width:600px"><h1>Create Account</h1><?php show_flash();?><form method="post" class="card p-4 mt-4 register-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="form-control mb-3" name="full_name" placeholder="Full name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" name="phone" placeholder="Phone"><input class="form-control mb-3" type="password" name="password" placeholder="Password" minlength="6" required><input class="form-control mb-3" type="password" name="confirm" placeholder="Confirm password" required><button class="btn btn-gold">Register</button></form></div></section><?php include 'includes/footer.php';?>
